// Hand-written. Not generated by Speakeasy.
//
// Guards the fix for lists Authlete returns in an order of its own. See
// internal/provider/planmodifiers/unordered_list.go for why a plan modifier
// rather than a custom type.
package provider

import (
	"context"
	"testing"

	"github.com/authlete/terraform-provider-authlete/internal/provider/planmodifiers"
	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/tfsdk"
	"github.com/hashicorp/terraform-plugin-framework/types"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

func strList(t *testing.T, vals ...string) types.List {
	t.Helper()
	elems := make([]types.String, 0, len(vals))
	for _, v := range vals {
		elems = append(elems, types.StringValue(v))
	}
	lv, diags := types.ListValueFrom(context.Background(), types.StringType, elems)
	if diags.HasError() {
		t.Fatalf("building list: %v", diags)
	}
	return lv
}

// planOrder runs the modifier and returns the resulting plan value.
func planOrder(t *testing.T, state, config types.List, creating bool) types.List {
	t.Helper()
	sch := schema.Schema{Attributes: map[string]schema.Attribute{
		"l": schema.ListAttribute{Optional: true, ElementType: types.StringType},
	}}
	objType := sch.Type().TerraformType(context.Background())

	raw := tftypes.NewValue(objType, map[string]tftypes.Value{
		"l": tftypes.NewValue(tftypes.List{ElementType: tftypes.String}, []tftypes.Value{}),
	})
	if creating {
		raw = tftypes.NewValue(objType, nil)
	}

	req := planmodifier.ListRequest{
		Path:        path.Root("l"),
		StateValue:  state,
		ConfigValue: config,
		State:       tfsdk.State{Schema: sch, Raw: raw},
	}
	resp := planmodifier.ListResponse{PlanValue: config}
	planmodifiers.KeepOrderWhenUnchanged().PlanModifyList(context.Background(), req, &resp)
	if resp.Diagnostics.HasError() {
		t.Fatalf("diagnostics: %v", resp.Diagnostics.Errors())
	}
	return resp.PlanValue
}

// TestReorderedListPlansNoChange is the fix. Authlete returns these lists in
// its own order; the plan must not offer to rewrite them.
func TestReorderedListPlansNoChange(t *testing.T) {
	state := strList(t, "REFRESH_TOKEN", "AUTHORIZATION_CODE")
	config := strList(t, "AUTHORIZATION_CODE", "REFRESH_TOKEN")

	got := planOrder(t, state, config, false)
	if !got.Equal(state) {
		t.Errorf("plan was %v, want the order already in state %v.\n\n"+
			"The configuration lists the same elements in a different order. "+
			"Keeping the stored order is what stops the plan offering the same "+
			"change on every run.", got, state)
	}
}

// TestRealChangesStillPlan: only a permutation may be suppressed.
func TestRealChangesStillPlan(t *testing.T) {
	for name, tc := range map[string]struct{ state, config types.List }{
		"element added":    {strList(t, "A"), strList(t, "A", "B")},
		"element removed":  {strList(t, "A", "B"), strList(t, "A")},
		"element replaced": {strList(t, "A", "B"), strList(t, "A", "C")},
		"emptied":          {strList(t, "A"), strList(t)},
		"duplicate added":  {strList(t, "A"), strList(t, "A", "A")},
	} {
		t.Run(name, func(t *testing.T) {
			got := planOrder(t, tc.state, tc.config, false)
			if !got.Equal(tc.config) {
				t.Errorf("plan was %v, want the configured value %v.\n\n"+
					"This is a real change, not a reordering. Suppressing it would "+
					"silently discard what the practitioner wrote.", got, tc.config)
			}
		})
	}
}

// TestCreationIsUntouched: there is no prior order to keep.
func TestCreationIsUntouched(t *testing.T) {
	config := strList(t, "B", "A")
	if got := planOrder(t, types.ListNull(types.StringType), config, true); !got.Equal(config) {
		t.Errorf("plan was %v, want %v on create", got, config)
	}
}

// TestUnsetListIsUntouched: a null configuration means no opinion, and the
// modifier must not substitute the stored value for it.
func TestUnsetListIsUntouched(t *testing.T) {
	null := types.ListNull(types.StringType)
	if got := planOrder(t, strList(t, "A"), null, false); !got.Equal(null) {
		t.Errorf("plan was %v, want null left alone", got)
	}
}

// reorderingLists are the attributes Authlete returns in an order of its own.
//
// Established live rather than guessed: a service and a client were created
// with every list written deliberately unsorted, and these came back permuted.
// The nine service lists that kept their order are deliberately absent.
var reorderingLists = map[string][]string{
	"authlete_service": {
		"supported_attachments",
		"supported_claim_types",
		"supported_claims",
		"supported_displays",
		"supported_grant_types",
		"supported_prompt_values",
		"supported_response_types",
		// supported_scopes is absent on purpose: it is a list of objects whose
		// server-filled fields differ from a configuration naming only the
		// scope, so it is not a pure reordering. See the overlay.
		"supported_service_profiles",
		"supported_token_auth_methods",
	},
	"authlete_client": {
		"grant_types",
		"response_modes",
		"response_types",
	},
}

// TestReorderingListsCarryTheModifier guards the overlay entries.
//
// The plan modifier only runs where the overlay attaches it. Dropping an entry
// leaves the attribute planning a change on every run, and nothing else
// notices: the provider still builds, every other test still passes, and the
// failure only shows up as a plan that will not settle.
func TestReorderingListsCarryTheModifier(t *testing.T) {
	for _, tc := range []struct {
		name     string
		resource resource.Resource
	}{
		{"authlete_service", NewServiceResource()},
		{"authlete_client", NewClientResource()},
	} {
		t.Run(tc.name, func(t *testing.T) {
			attrs := resourceSchema(t, tc.resource).Attributes
			for _, name := range reorderingLists[tc.name] {
				// A list of objects is a ListNestedAttribute rather than a
				// ListAttribute; both carry []planmodifier.List.
				var modifiers int
				switch attr := attrs[name].(type) {
				case schema.ListAttribute:
					modifiers = len(attr.PlanModifiers)
				case schema.ListNestedAttribute:
					modifiers = len(attr.PlanModifiers)
				default:
					t.Errorf("%s has no list attribute %q (got %T)", tc.name, name, attrs[name])
					continue
				}
				if modifiers == 0 {
					t.Errorf("%s.%s has no plan modifier.\n\n"+
						"Authlete returns this list in an order of its own, so a "+
						"configuration listing the same values in a different order "+
						"plans a change on every run and never converges.\n\n"+
						"Restore the x-speakeasy-plan-modifiers entry for this property "+
						"in .speakeasy/terraform_overlay.yaml.", tc.name, name)
				}
			}
		})
	}
}
